package containers

import (
	"time"

	"github.com/wuxu92/azwise"
)

// ContainerGroup provides resource knowledge for Microsoft.ContainerInstance/containerGroups.
//
// Contributing Terraform resource: azurerm_container_group.
//
// Sources:
//   - terraform-provider-azurerm internal/services/containers/container_group_resource.go
//     (schema L53-512, CustomizeDiff L513-520, Create L642-772)
//   - go-azure-sdk resource-manager/containerinstance/2025-09-01/containerinstance:
//     model_containergrouppropertiesproperties.go, model_ipaddress.go, constants.go (enums).
//
// Notes:
//   - Nearly every field is ForceNew — container groups are largely immutable in Azure.
//   - ip_address_type maps to properties.ipAddress.type; AzureRM adds a "None" sentinel
//     that means "omit ipAddress" (not an ARM enum value), so AllowedValues uses the ARM
//     SDK set Public/Private.
//   - CustomizeDiff requires ip_address_type = None when priority = Spot — a value-conditional
//     rule not expressible declaratively, left as a note.
//   - container blocks (properties.containers[*]) and init_container blocks carry per-element
//     cpu/memory/port validators; those are array-element paths, skipped per azwise policy.
type ContainerGroup struct {
	azwise.BaseKnowledge
}

var _ azwise.ResourceKnowledge = (*ContainerGroup)(nil)

// NewContainerGroup returns knowledge for the containerGroups resource.
func NewContainerGroup() *ContainerGroup {
	return &ContainerGroup{
		BaseKnowledge: azwise.BaseKnowledge{
			ResourceType: "Microsoft.ContainerInstance/containerGroups",
			ApiVersions:  []string{"2025-09-01"},
			TimeoutsConfig: &azwise.Timeouts{
				Create: 60 * time.Minute,
				Read:   5 * time.Minute,
				Update: 30 * time.Minute,
				Delete: 30 * time.Minute,
			},
			ForceNew: []azwise.ForceNewRule{
				{PropertyPath: "properties.osType"},
				{PropertyPath: "properties.sku"},
				{PropertyPath: "properties.restartPolicy"},
				{PropertyPath: "properties.priority"},
				{PropertyPath: "properties.subnetIds"},
				{PropertyPath: "properties.containers"},
				{PropertyPath: "properties.initContainers"},
				{PropertyPath: "properties.diagnostics"},
				{PropertyPath: "properties.dnsConfig"},
				{PropertyPath: "properties.imageRegistryCredentials"},
				{PropertyPath: "properties.encryptionProperties"},
				{PropertyPath: "properties.ipAddress.type"},
				{PropertyPath: "properties.ipAddress.dnsNameLabel"},
				{PropertyPath: "properties.ipAddress.autoGeneratedDomainNameLabelScope"},
			},
			StringRules: []azwise.StringRule{
				// ── ip_address_type → properties.ipAddress.type
				{
					PropertyPath:  "properties.ipAddress.type",
					AllowedValues: []string{"Public", "Private"},
					Message:       "must be one of Public or Private",
				},
				// ── os_type → properties.osType
				{
					PropertyPath:  "properties.osType",
					AllowedValues: []string{"Windows", "Linux"},
					Message:       "must be one of Windows or Linux",
				},
				// ── sku → properties.sku
				{
					PropertyPath:  "properties.sku",
					AllowedValues: []string{"Confidential", "Dedicated", "NotSpecified", "Standard"},
					Message:       "must be one of Confidential, Dedicated, NotSpecified or Standard",
				},
				// ── restart_policy → properties.restartPolicy
				{
					PropertyPath:  "properties.restartPolicy",
					AllowedValues: []string{"Always", "Never", "OnFailure"},
					Message:       "must be one of Always, Never or OnFailure",
				},
				// ── dns_name_label_reuse_policy → properties.ipAddress.autoGeneratedDomainNameLabelScope
				{
					PropertyPath:  "properties.ipAddress.autoGeneratedDomainNameLabelScope",
					AllowedValues: []string{"Noreuse", "ResourceGroupReuse", "SubscriptionReuse", "TenantReuse", "Unsecure"},
					Message:       "must be one of Noreuse, ResourceGroupReuse, SubscriptionReuse, TenantReuse or Unsecure",
				},
				// ── priority → properties.priority
				{
					PropertyPath:  "properties.priority",
					AllowedValues: []string{"Regular", "Spot"},
					Message:       "must be one of Regular or Spot",
				},
			},
			ArrayRules: []azwise.ArrayRule{
				// subnet_ids MaxItems 1.
				{PropertyPath: "properties.subnetIds", MaxItems: 1},
			},
			// subnet_ids conflicts with dns_name_label.
			ConflictsWith: []azwise.RelationalRule{
				{
					Paths:   []string{"properties.subnetIds", "properties.ipAddress.dnsNameLabel"},
					Message: "subnet_ids cannot be combined with dns_name_label",
				},
			},
			DefaultValues: []azwise.DefaultValue{
				// ip_address_type Default Public.
				{PropertyPath: "properties.ipAddress.type", Value: "Public"},
				// sku Default Standard.
				{PropertyPath: "properties.sku", Value: "Standard"},
				// restart_policy Default Always.
				{PropertyPath: "properties.restartPolicy", Value: "Always"},
				// dns_name_label_reuse_policy Default Unsecure.
				{PropertyPath: "properties.ipAddress.autoGeneratedDomainNameLabelScope", Value: "Unsecure"},
			},
			// os_type and container are Required for creation.
			RequiredFields: []string{
				"properties.osType",
				"properties.containers",
			},
			// Read-only properties returned by GET but absent from the create body.
			ComputedFields: []string{
				"properties.ipAddress.ip",
				"properties.ipAddress.fqdn",
				"properties.instanceView",
				"properties.provisioningState",
			},
		},
	}
}

// Self-registers into the azwise registry (no central register.go).
func init() { azwise.Register(NewContainerGroup()) }
